// Local screenshot annotations. Nothing is uploaded or sent automatically.
export function installAnnotations({toast}) {
 const button=document.createElement('button');button.className='text-btn';button.id='annotateScreen';button.textContent='✎ Annoter';button.setAttribute('aria-label','Annoter l’écran');button.title='Entourer une zone et expliquer ce qui ne va pas';document.getElementById('help').before(button);
 const dialog=document.createElement('dialog');dialog.id='warlikeAnnotation';dialog.setAttribute('aria-label','Annoter WarLike Studio');dialog.innerHTML=`<header><div><strong>✎ Annoter WarLike Studio</strong><small>Entoure la zone, ajoute une note, puis joins le PNG à notre conversation.</small></div><button data-close aria-label="Fermer les annotations">×</button></header><nav aria-label="Outils d’annotation"><button data-tool="pen" aria-pressed="true">✎ Crayon</button><button data-tool="arrow" aria-pressed="false">↗ Flèche</button><button data-tool="ellipse" aria-pressed="false">◯ Entourer</button><button data-tool="rect" aria-pressed="false">□ Cadre</button><button data-tool="note" aria-pressed="false">① Note</button><label>Couleur <input type="color" value="#ff654f" aria-label="Couleur du dessin"></label><button data-undo>Annuler</button><button data-clear>Tout effacer</button><button data-capture>Nouvelle capture</button><label class="annotation-import">Importer une capture<input type="file" accept="image/png,image/jpeg,image/webp" hidden></label></nav><div class="annotation-content"><div class="annotation-stage"><canvas tabindex="0" aria-label="Capture à annoter : tracer avec la souris ou le doigt"></canvas><p class="annotation-empty" hidden>Aucune capture. Ferme cette fenêtre et réessaie, ou importe une capture d’écran.</p></div><aside><h3>Ce qui ne va pas</h3><p>Clique sur ① Note, puis sur une zone de la capture.</p><div class="annotation-notes"></div><label>Commentaire général<textarea class="annotation-summary" placeholder="Le résultat attendu, le problème rencontré…" maxlength="4000"></textarea></label></aside></div><footer><output role="status">Capture locale · aucun envoi automatique</output><button data-copy>Copier les notes</button><button data-export class="primary-btn">Télécharger le PNG</button></footer>`;document.body.append(dialog);
 const canvas=dialog.querySelector('canvas'),ctx=canvas.getContext('2d'),status=dialog.querySelector('output'),notes=dialog.querySelector('.annotation-notes'),summary=dialog.querySelector('.annotation-summary');
 let background=null,marks=[],draft=null,tool='pen',busy=false,color='#ff654f';
 function point(e){const r=canvas.getBoundingClientRect();return {x:Math.max(0,Math.min(canvas.width,(e.clientX-r.left)*canvas.width/r.width)),y:Math.max(0,Math.min(canvas.height,(e.clientY-r.top)*canvas.height/r.height))};}
 function paintMark(c,m){c.save();c.strokeStyle=m.color;c.fillStyle=m.color;c.lineWidth=3;c.lineCap='round';c.lineJoin='round';const a=m.points[0],b=m.points.at(-1);c.beginPath();if(m.type==='pen'){c.moveTo(a.x,a.y);for(const p of m.points)c.lineTo(p.x,p.y);if(m.points.length===1)c.lineTo(a.x+.1,a.y+.1);c.stroke();}else if(m.type==='rect')c.strokeRect(a.x,a.y,b.x-a.x,b.y-a.y);else if(m.type==='ellipse'){c.ellipse((a.x+b.x)/2,(a.y+b.y)/2,Math.max(1,Math.abs(b.x-a.x)/2),Math.max(1,Math.abs(b.y-a.y)/2),0,0,Math.PI*2);c.stroke();}else if(m.type==='arrow'){const angle=Math.atan2(b.y-a.y,b.x-a.x);c.moveTo(a.x,a.y);c.lineTo(b.x,b.y);c.moveTo(b.x-14*Math.cos(angle-.5),b.y-14*Math.sin(angle-.5));c.lineTo(b.x,b.y);c.lineTo(b.x-14*Math.cos(angle+.5),b.y-14*Math.sin(angle+.5));c.stroke();}else if(m.type==='note'){c.arc(a.x,a.y,14,0,Math.PI*2);c.fill();c.fillStyle='#101720';c.font='bold 15px sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText(String(m.number),a.x,a.y);}c.restore();}
 function redraw(){ctx.clearRect(0,0,canvas.width,canvas.height);if(background)ctx.drawImage(background,0,0,canvas.width,canvas.height);for(const m of marks)paintMark(ctx,m);if(draft)paintMark(ctx,draft);dialog.querySelector('[data-undo]').disabled=!marks.length;dialog.querySelector('[data-export]').disabled=!background;}
 function renderNotes(){notes.replaceChildren();for(const m of marks.filter(x=>x.type==='note')){const label=document.createElement('label');label.textContent='Note '+m.number;const input=document.createElement('textarea');input.maxLength=2000;input.placeholder='Explique ce qui ne va pas ici…';input.value=m.text||'';input.setAttribute('aria-label','Texte de la note '+m.number);input.oninput=()=>m.text=input.value;label.append(input);notes.append(label);}}
 function reset(){marks=[];draft=null;summary.value='';renderNotes();redraw();}
 function setBackground(image){background=image;canvas.width=image.width;canvas.height=image.height;dialog.querySelector('.annotation-empty').hidden=true;canvas.hidden=false;reset();}
 async function capture(){if(busy)return;busy=true;button.disabled=true;status.textContent='Capture en cours…';const wasOpen=dialog.open;if(wasOpen)dialog.close();try{await new Promise(requestAnimationFrame);const {toCanvas}=await import('./vendor/html-to-image/index.js');const shot=await toCanvas(document.body,{width:innerWidth,height:innerHeight,pixelRatio:1,fontEmbedCSS:'',backgroundColor:'#252a31',filter:node=>node.id!=='warlikeAnnotation'&&node.tagName!=='SCRIPT'&&(!node.hidden)&&(!(node instanceof Element)||getComputedStyle(node).display!=='none')});setBackground(shot);status.textContent='Capture figée · dessine sur la zone à corriger';}catch(error){status.textContent='Capture impossible : importe une capture d’écran pour l’annoter.';toast('La capture a échoué. Tu peux importer une image dans Annoter.');if(!background){canvas.hidden=true;dialog.querySelector('.annotation-empty').hidden=false;}}finally{busy=false;button.disabled=false;if(!dialog.open)dialog.showModal();}}
 for(const host of [document.querySelector('#modal .modal-heading'),document.querySelector('#pluginFloat .floating-window-actions')]){if(!host)continue;const launcher=document.createElement('button');launcher.className='text-btn annotation-window-launch';launcher.textContent='✎ Annoter';launcher.setAttribute('aria-label','Annoter cette fenêtre');launcher.title='Capturer cette fenêtre · Alt+Maj+A';launcher.onclick=capture;host.insertBefore(launcher,host.lastElementChild);}
 document.addEventListener('keydown',e=>{if(e.altKey&&e.shiftKey&&e.code==='KeyA'&&!dialog.open){e.preventDefault();e.stopImmediatePropagation();capture();}},true);
 button.onclick=()=>{if(background)dialog.showModal();else capture();};dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.querySelector('[data-capture]').onclick=capture;
 for(const b of dialog.querySelectorAll('[data-tool]'))b.onclick=()=>{tool=b.dataset.tool;dialog.querySelectorAll('[data-tool]').forEach(el=>el.setAttribute('aria-pressed',String(el===b)));};dialog.querySelector('input[type=color]').oninput=e=>color=e.target.value;
 canvas.onpointerdown=e=>{if(e.button!==0||!background)return;e.preventDefault();const p=point(e);if(tool==='note'){const number=Math.max(0,...marks.filter(m=>m.type==='note').map(m=>m.number))+1;marks.push({type:tool,color,points:[p],number,text:''});renderNotes();redraw();notes.lastElementChild.querySelector('textarea').focus();return;}draft={type:tool,color,points:[p]};canvas.setPointerCapture(e.pointerId);redraw();};
 canvas.onpointermove=e=>{if(!draft)return;const p=point(e);if(draft.type==='pen')draft.points.push(p);else draft.points[1]=p;redraw();};canvas.onpointerup=()=>{if(!draft)return;marks.push(draft);draft=null;redraw();};canvas.onpointercancel=()=>{draft=null;redraw();};
 dialog.querySelector('[data-undo]').onclick=()=>{marks.pop();renderNotes();redraw();};dialog.querySelector('[data-clear]').onclick=()=>{marks=[];draft=null;renderNotes();redraw();};dialog.addEventListener('keydown',e=>{e.stopPropagation();if(e.key==='Escape')return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!e.target.matches('textarea,input')){e.preventDefault();marks.pop();renderNotes();redraw();}});
 dialog.querySelector('input[type=file]').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>20*1024*1024){status.textContent='Choisis une image de moins de 20 Mo.';return;}const url=URL.createObjectURL(file);try{const image=new Image();image.src=url;await image.decode();if(image.width*image.height>24000000)throw new Error('Image trop grande');setBackground(image);status.textContent='Capture importée · prête à annoter';}catch{status.textContent='Image non reconnue ou trop grande (24 mégapixels maximum).';}finally{URL.revokeObjectURL(url);e.target.value='';}};
 function noteText(){return ['WarLike Studio — retour sur la capture',...marks.filter(m=>m.type==='note').map(m=>`${m.number}. ${m.text||'(zone signalée)'}`),summary.value].filter(Boolean).join('\n\n');}
 dialog.querySelector('[data-copy]').onclick=async()=>{try{await navigator.clipboard.writeText(noteText());status.textContent='Notes copiées. Tu peux les coller dans la conversation.';}catch{status.textContent='Copie indisponible : les notes seront incluses dans le PNG.';}};
 dialog.querySelector('[data-export]').onclick=()=>{if(!background)return;redraw();const output=document.createElement('canvas'),c=output.getContext('2d'),width=Math.max(800,canvas.width),lines=[];c.font='16px sans-serif';for(const paragraph of noteText().split('\n')){let line='';for(const word of paragraph.split(/\s+/)){const candidate=line?line+' '+word:word;if(c.measureText(candidate).width>width-48&&line){lines.push(line);line=word;}else line=candidate;}lines.push(line);}output.width=width;output.height=canvas.height+Math.max(100,lines.length*24+40);c.fillStyle='#19222c';c.fillRect(0,0,output.width,output.height);c.drawImage(canvas,0,0);c.font='16px sans-serif';c.fillStyle='#f1f3f6';lines.forEach((line,i)=>c.fillText(line,24,canvas.height+30+i*24));output.toBlob(blob=>{if(!blob){status.textContent='Export impossible. Réessaie avec une nouvelle capture.';return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='warlike-retour-'+new Date().toISOString().slice(0,19).replace(/[:T]/g,'-')+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);status.textContent='PNG téléchargé. Joins-le à notre conversation pour me montrer le problème.';},'image/png');};
}
